/* App service worker. Generated by scripts/postbuild.mjs from scripts/sw-template.js. Do not edit out/sw.js directly. */
const VERSION = "__SW_VERSION__";
const PRECACHE_URLS = __SW_PRECACHE__;
const PRECACHE = "sth-precache-" + VERSION;
const RUNTIME = "sth-runtime-" + VERSION;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      const queue = PRECACHE_URLS.slice();
      const worker = async () => {
        while (queue.length) {
          const url = queue.shift();
          try {
            const res = await fetch(new Request(url, { cache: "reload", credentials: "same-origin" }));
            if (res.ok) await cache.put(url, res);
          } catch (e) {
            /* ignore single failures, the file will be fetched at runtime */
          }
        }
      };
      await Promise.all(Array.from({ length: 6 }, worker));
      // First install: nothing to protect, activate straight away.
      if (!self.registration.active) await self.skipWaiting();
    })()
  );
});

self.addEventListener("message", (event) => {
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => k.startsWith("sth-") && k !== PRECACHE && k !== RUNTIME)
          .map((k) => caches.delete(k))
      );
      await self.clients.claim();
    })()
  );
});

function normalize(pathname) {
  let p = pathname;
  if (p.length > 1 && p.endsWith("/")) p = p.slice(0, -1);
  if (p.endsWith(".html")) p = p.slice(0, -5);
  if (p.endsWith("/index")) p = p.slice(0, -6);
  return p || "/";
}

function cleanResponse(res) {
  if (!res.redirected) return res;
  return res.blob().then(
    (body) => new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers })
  );
}

async function navigate(req, url) {
  const cache = await caches.open(PRECACHE);
  const cached = await cache.match(normalize(url.pathname));
  if (cached) return cleanResponse(cached);
  try {
    return await fetch(req);
  } catch (e) {
    const fallback = (await cache.match("/dashboard")) || (await cache.match("/"));
    if (fallback) return cleanResponse(fallback);
    return new Response("You are offline. Please check your internet connection.", {
      status: 503,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  }
}

async function cachedOrNetwork(req, cachedPath) {
  const cache = await caches.open(PRECACHE);
  const cached = await cache.match(cachedPath);
  if (cached) return cleanResponse(cached);
  return fetch(req);
}

async function asset(req, url) {
  const pre = await caches.open(PRECACHE);
  let hit = (await pre.match(req)) || (await pre.match(url.pathname));
  if (hit) return hit;
  const runtime = await caches.open(RUNTIME);
  hit = await runtime.match(req);
  try {
    const res = await fetch(req);
    const p = url.pathname;
    if (res.ok && (p.startsWith("/_next/static/") || p.startsWith("/fonts/") || p.startsWith("/icons/"))) {
      runtime.put(req, res.clone());
    }
    return res;
  } catch (e) {
    if (hit) return hit;
    throw e;
  }
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // Firebase / Google APIs go straight to the network
  if (url.pathname.startsWith("/__/")) return; // Firebase reserved URLs
  if (url.pathname === "/sw.js") return;
  // A business's own link (/c/<name>) is its login page and keeps its address (also offline and in the installed app).
  if (/^\/c\/[a-z0-9-]{1,30}\/?$/i.test(url.pathname) && req.mode === "navigate") {
    event.respondWith(cachedOrNetwork(req, "/login"));
    return;
  }
  // Its install file: the shared client install file, read relative to this address.
  if (/^\/c\/[a-z0-9-]{1,30}\/app\.webmanifest$/i.test(url.pathname)) {
    event.respondWith(cachedOrNetwork(req, "/client.webmanifest"));
    return;
  }
  if (req.mode === "navigate") {
    event.respondWith(navigate(req, url));
    return;
  }
  event.respondWith(asset(req, url));
});
